def summarize(records):
    if type(records) is not list:
        raise ValueError("records must be a list")
    totals = {}
    for record in records:
        if type(record) is not dict or set(record) != {"category", "amount"}:
            raise ValueError("invalid record fields")
        category, amount = record["category"], record["amount"]
        if type(category) is not str or not category.strip() or type(amount) is not int:
            raise ValueError("invalid category or amount")
        category = category.strip()
        totals[category] = totals.get(category, 0) + amount
    return totals

import json
import sys
from totals import summarize

def main():
    try:
        totals = summarize(json.load(sys.stdin))
    except (ValueError, TypeError, KeyError):
        return 2
    print(json.dumps({"totals": [{"category": key, "amount": totals[key]} for key in sorted(totals)], "net": sum(totals.values())}))
    return 0

if __name__ == "__main__":
    sys.exit(main())

import unittest
from totals import summarize

class TotalsTests(unittest.TestCase):
    def test_refunds_and_trim(self):
        self.assertEqual(summarize([{"category": " A ", "amount": 5}, {"category": "A", "amount": -8}]), {"A": -3})
    def test_empty(self):
        self.assertEqual(summarize([]), {})
    def test_bad_records(self):
        for value in ({}, None, [None], [{"category":"A", "amount":True}], [{"category":" ", "amount":1}], [{"category":"A", "amount":1, "extra":2}]):
            with self.subTest(value=value), self.assertRaises(ValueError):
                summarize(value)

if __name__ == "__main__":
    unittest.main()
